<?php $u=member_required();$supplies=Db::all('SELECT r.*,m.name_ar,m.name_en FROM supply_requests r JOIN materials m ON m.id=r.material_id WHERE r.user_id=? ORDER BY r.id DESC LIMIT 100',[$u['id']]);$orders=Db::all('SELECT o.*,m.name_ar,m.name_en FROM orders o JOIN batches b ON b.id=o.batch_id JOIN materials m ON m.id=b.material_id WHERE o.user_id=? ORDER BY o.id DESC LIMIT 100',[$u['id']]);$tickets=Db::all('SELECT * FROM tickets WHERE user_id=? ORDER BY id DESC LIMIT 50',[$u['id']]);$sellerRows=Db::all("SELECT o.id,o.quantity_g,o.subtotal,o.status,COALESCE((SELECT SUM(s.amount) FROM settlements s WHERE s.order_id=o.id AND s.type='seller'),0) AS settled,m.name_ar,m.name_en FROM orders o JOIN batches b ON b.id=o.batch_id JOIN parties p ON p.id=b.supplier_id JOIN materials m ON m.id=b.material_id WHERE p.user_id=? ORDER BY o.id DESC LIMIT 100",[$u['id']]); ?>
<section class="page-hero container"><div class="eyebrow"><?= t('كل خطواتك، في مكان واحد','EVERY STEP, IN ONE PLACE') ?></div><h1><?= t('أهلاً، ','Hello, ') ?><?= e($u['name']) ?>.</h1><p dir="ltr"><?= e($u['phone']) ?></p><div class="hero-buttons"><a class="button button-green" href="<?= e(url('sell')) ?>"><?= t('طلب بيع جديد','New selling request') ?></a><a class="button button-outline" href="<?= e(url('market')) ?>"><?= t('شراء مواد','Source materials') ?></a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="logout"><button class="button button-outline"><?= t('خروج','Sign out') ?></button></form></div></section><section class="container page-section account-grid"><article class="form-card"><h2><?= t('طلبات البيع','Selling requests') ?></h2><?php if(!$supplies): ?><p class="caption"><?= t('طلبات بيعك هتظهر هنا.','Your selling requests will appear here.') ?></p><?php endif; ?><?php foreach($supplies as $r): ?><div class="record-line"><div><b><?= e(localized($r)) ?> · <?= qty((int)$r['quantity_g']) ?></b><p><?= e($r['public_code']) ?> · <?= e(state_label($r['handover'])) ?></p></div><?= badge($r['status']) ?></div><?php endforeach; ?></article><article class="form-card"><h2><?= t('طلبات الشراء','Purchase orders') ?></h2><?php if(!$orders): ?><p class="caption"><?= t('طلبات مصنعك هتظهر هنا.','Your business orders will appear here.') ?></p><?php endif; ?><?php foreach($orders as $o): ?><a class="record-line" href="<?= e(url('order',['id'=>$o['id']])) ?>"><div><b><?= e(localized($o)) ?> · <?= money((int)$o['total']) ?></b><p><?= e($o['code']) ?></p></div><?= badge($o['status']) ?></a><?php endforeach; ?></article><article class="form-card"><h2><?= t('مبيعاتي وتسوياتي','My sales & settlements') ?></h2><?php if(!$sellerRows): ?><p class="caption"><?= t('بعد بيع دفعتك، تظهر الكمية والمستحق والتسوية هنا.','After your batch sells, quantity, payable amount and settlement appear here.') ?></p><?php endif; ?><?php foreach($sellerRows as $r): ?><div class="record-line"><div><b><?= e(localized($r)) ?> · <?= qty((int)$r['quantity_g']) ?></b><p>HS-SL-<?= e($r['id']??'') ?></p><small><?= t('قيمة المادة: ','Material value: ') ?><?= money((int)$r['subtotal']) ?> · <?= t('تم تحويل: ','Transferred: ') ?><?= money((int)$r['settled']) ?></small></div><?= badge($r['status']) ?></div><?php endforeach; ?></article><article class="form-card"><h2><?= t('رسائل الدعم','Support conversations') ?></h2><?php if(!$tickets): ?><p class="caption"><?= t('ردود فريق حصاد هتظهر هنا.','Hasad team replies will appear here.') ?></p><?php endif; ?><?php foreach($tickets as $ticket): ?><div class="ticket-summary"><div class="record-line"><b><?= e($ticket['subject']) ?></b><?= badge($ticket['status']) ?></div><p><?= nl2br(e($ticket['message'])) ?></p><?php if($ticket['response']): ?><blockquote><?= nl2br(e($ticket['response'])) ?></blockquote><?php endif; ?></div><?php endforeach; ?><a class="text-link" href="<?= e(url('contact')) ?>"><?= t('رسالة جديدة','New message') ?></a></article></section>
